from google.cloud import monitoring_v3
from datetime import datetime, timedelta

def compare_metric_series(project_id: str, metric_type: str, filter_set_1: dict, filter_set_2: dict, minutes_ago: int = 60):
    client = monitoring_v3.MetricServiceClient()
    project_name = f"projects/{project_id}"

    now = datetime.utcnow()
    end_time = now
    start_time = now - timedelta(minutes=minutes_ago)

    interval = monitoring_v3.TimeInterval(
        end_time={"seconds": int(end_time.timestamp())},
        start_time={"seconds": int(start_time.timestamp())},
    )

    def _get_time_series_data(filters: dict):
        filter_string = ""
        for key, value in filters.items():
            filter_string += f'metric.labels.{key} = "{value}" AND '
        if filter_string:
            filter_string = filter_string[:-5]

        query = f"fetch gce_instance | metric {metric_type} | filter {filter_string} | within {minutes_ago}m"
        results = client.query_time_series(
            name=project_name,
            query=query,
            interval=interval,
        )

        time_series_data = []
        for time_series in results:
            for point in time_series.points:
                time_series_data.append({
                    "metric": time_series.metric.type,
                    "value": point.value.double_value,
                    "timestamp": point.interval.end_time.timestamp(),
                    "resource": {
                        "type": time_series.resource.type,
                        "labels": dict(time_series.resource.labels)
                    }
                })
        return time_series_data

    data_series_1 = _get_time_series_data(filter_set_1)
    data_series_2 = _get_time_series_data(filter_set_2)

    return {
        "series_1": {
            "filter": filter_set_1,
            "data": data_series_1
        },
        "series_2": {
            "filter": filter_set_2,
            "data": data_series_2
        }
    }

from google.cloud import monitoring_v3
import os

def get_monitoring_client():
    """Returns a Google Cloud Monitoring MetricServiceClient."""
    return monitoring_v3.MetricServiceClient()

def get_project_id():
    """Returns the Google Cloud Project ID from environment variables or default."""
    # In a real application, consider using google.auth.default() to get project ID
    # or explicitly passing it.
    return os.getenv("GOOGLE_CLOUD_PROJECT", "your-gcp-project-id")

from datetime import datetime
from typing import List, Dict, Any

class MetricPoint:
    def __init__(self, value: float, timestamp: datetime):
        self.value = value
        self.timestamp = timestamp

    def to_dict(self):
        return {"value": self.value, "timestamp": self.timestamp.isoformat()}

class TimeSeries:
    def __init__(self, metric_type: str, resource_labels: Dict[str, str], points: List[MetricPoint]):
        self.metric_type = metric_type
        self.resource_labels = resource_labels
        self.points = points

    def to_dict(self):
        return {
            "metric_type": self.metric_type,
            "resource_labels": self.resource_labels,
            "points": [point.to_dict() for point in self.points]
        }

def normalize_time_series_response(response) -> List[TimeSeries]:
    """Normalizes Google Cloud Monitoring ListTimeSeriesResponse to a list of TimeSeries objects."""
    normalized_data = []
    for ts_data in response:
        metric_type = ts_data.metric.type
        resource_labels = dict(ts_data.resource.labels)
        points = []
        for point in ts_data.points:
            # Google Cloud Monitoring timestamps are protobuf Timestamp objects
            # Convert to datetime object for easier handling
            timestamp_dt = datetime.fromtimestamp(point.interval.end_time.timestamp())
            value = point.value.double_value # Assuming double_value for simplicity
            points.append(MetricPoint(value, timestamp_dt))
        normalized_data.append(TimeSeries(metric_type, resource_labels, points))
    return normalized_data
